SELECT
    count(*)
FROM
    BASIL_SEC_PRD.PREP_MASTER_ORDER pmo
    JOIN BASIL_ODS_PRD.MASTER_CUSTOMER mc USING(MC_OID)
    JOIN BASIL_SEC_PRD.SUPPORT_CLIENT_ATTRIBUTE_VALUES scavstat ON pmo.ORDER_STATUS = scavstat.SCV_OID
    LEFT JOIN BASIL_SEC_PRD.XREF_RESPONSE resp USING(MO_OID)
    LEFT JOIN BASIL_SEC_PRD.USERS user ON resp.RESPONSE_BY = user.U_OID
    LEFT JOIN BASIL_SEC_PRD.SUPPORT_CLIENT_ATTRIBUTE_VALUES scavstatus ON pmo.ORDER_STATUS = scavstatus.SCV_OID
    LEFT JOIN BASIL_SEC_PRD.SUPPORT_CLIENT_ATTRIBUTE_VALUES scavdept ON pmo.ORDER_DEPT = scavdept.SCV_OID
    LEFT JOIN BASIL_SEC_PRD.SUPPORT_CLIENT_ATTRIBUTE_VALUES scavtype ON pmo.ORDER_TYPE = scavtype.SCV_OID


        AND mc.MC_OID = #{id}


        AND

            #{item}



        AND scavdept.SCV_OID = #{department}


        AND scavtype.SCV_OID = #{type}


        AND scavstatus.SCV_OID = #{status}


        AND
        pmo.MO_OID IN (
        SELECT pxm.MO_OID
        FROM BASIL_SEC_PRD.PREP_XREF_MATERIALS AS pxm
        WHERE pxm.MSN_OID IN (
        SELECT msn.MSN_OID
        FROM BASIL_ODS_PRD.MASTER_SERIAL_NUMBER AS msn
        WHERE msn.SERIAL_NUMBER IN

            #{item}

        )
        )


        AND user.NAME = #{responder} OR user.NAME IS NULL


        AND pmo.ORDER_DATE BETWEEN #{createdFromDate} AND #{createdToDate}

SELECT pmo.MO_OID as ticketId, scavstatus.VALUE as status, scavdept.VALUE as department, scavtype.VALUE as type, mc.CUSTOMER_ORGANIZATION as customerOrganization, pmo.ORDER_DATE as createdDate, user.NAME as responder FROM BASIL_SEC_PRD.PREP_MASTER_ORDER pmo JOIN BASIL_ODS_PRD.MASTER_CUSTOMER mc USING(MC_OID) JOIN BASIL_SEC_PRD.SUPPORT_CLIENT_ATTRIBUTE_VALUES scavstat ON pmo.ORDER_STATUS = scavstat.SCV_OID LEFT JOIN BASIL_SEC_PRD.XREF_RESPONSE resp USING(MO_OID) LEFT JOIN BASIL_SEC_PRD.USERS user ON resp.RESPONSE_BY = user.U_OID
LEFT JOIN BASIL_SEC_PRD.SUPPORT_CLIENT_ATTRIBUTE_VALUES scavstatus ON pmo.ORDER_STATUS = scavstatus.SCV_OID LEFT JOIN BASIL_SEC_PRD.SUPPORT_CLIENT_ATTRIBUTE_VALUES scavdept ON pmo.ORDER_DEPT = scavdept.SCV_OID LEFT JOIN BASIL_SEC_PRD.SUPPORT_CLIENT_ATTRIBUTE_VALUES scavtype ON pmo.ORDER_TYPE = scavtype.SCV_OID
pmo.ACKNOWLEDGED = 0
AND mc.MC_OID = #{id}
AND
#{item}
AND scavdept.SCV_OID = #{department}
AND scavtype.SCV_OID = #{type}
AND scavstatus.SCV_OID = #{status}
AND pmo.MO_OID IN ( SELECT pxm.MO_OID FROM BASIL_SEC_PRD.PREP_XREF_MATERIALS AS pxm WHERE pxm.MSN_OID IN ( SELECT msn.MSN_OID FROM BASIL_ODS_PRD.MASTER_SERIAL_NUMBER AS msn WHERE msn.SERIAL_NUMBER IN
#{item}
) )
AND LOWER(user.NAME) LIKE CONCAT ('%', LOWER(#{responder}), '%')
AND pmo.ORDER_DATE BETWEEN #{createdFromDate} AND #{createdToDate}
ORDER BY ${sortColumns}
LIMIT #{offset,jdbcType=INTEGER},#{count,jdbcType=INTEGER}

SELECT xm.XM_OID AS xm_oid, IF(xm.STATUS = 107, 1, 0) AS inventory, IF(xm.STATUS = 110, 1, 0) AS outForRepair, IF(xm.STATUS = 108, 1, 0) AS quarantine, IF(xm.STATUS = 111, 1, 0) AS awaitingQaCa, IF(xm.STATUS = 112, 1, 0) AS readyToShip, mo.MO_OID AS rmaNumber, xm.RECEIVED_DATE as dateReceived, xm.QUARANTINE_DATE as quarantineDate, part.PART_NUMBER_LONG as partNumber, msn.SERIAL_NUMBER as serialNumber, part.VERSION_NUMBER as versionNumber, part2.PART_NUMBER_LONG as partNumber2, msn2.SERIAL_NUMBER as serialNumber2 , part2.VERSION_NUMBER as versionNumber2, xm.REPAIR_DATE as completedDate, (SELECT VALUE FROM BASIL_ODS_PRD.SUPPORT_ATTRIBUTE_VALUES WHERE SAV_OID = xm.CUSTOMER_REPORTED_ISSUE) as reportedIssue, (SELECT VALUE FROM BASIL_ODS_PRD.SUPPORT_ATTRIBUTE_VALUES WHERE SAV_OID = xm.ESD_KIT) as esdKit, (SELECT VALUE FROM BASIL_ODS_PRD.SUPPORT_ATTRIBUTE_VALUES WHERE SAV_OID = xm.PHYSICAL_DAMAGE_PRESENT) as physicalDamagePresent, (SELECT VALUE FROM BASIL_ODS_PRD.SUPPORT_ATTRIBUTE_VALUES WHERE SAV_OID = xm.CUSTOMER_ISSUE_REPRODUCED) as customerIssueReproduced, xm.CUSTOMER_REPORTED_ISSUE_EXT as reportedIssueExt, xm.TAMPER_LOG_INTERPRETATION as tamperLog, (SELECT VALUE FROM BASIL_ODS_PRD.SUPPORT_ATTRIBUTE_VALUES WHERE SAV_OID = xm.ERROR_MESSAGE) as errorMessage, (SELECT VALUE FROM BASIL_ODS_PRD.SUPPORT_ATTRIBUTE_VALUES WHERE SAV_OID = xm.BATTERY_VOLTAGE) as batteryVoltage, xm.REPAIR_DATE as repairDate, (SELECT VALUE FROM BASIL_ODS_PRD.SUPPORT_ATTRIBUTE_VALUES WHERE SAV_OID = xm.DEPARTMENT) as department, (SELECT TRACKING_NUMBER FROM BASIL_ODS_PRD.XREF_SHIP xs WHERE xs.BOX_OID = xm.BOX_OID) as trackingNumber, (SELECT CUSTOMER_ORGANIZATION FROM BASIL_ODS_PRD.MASTER_CUSTOMER mc WHERE mc.MC_OID = mo.MC_OID) as customerName, emp.NAME as assighness, xm.TECH_NOTES as techNotes, msn.WARRANTY_END_DATE as warrantyEndDate, msn.WARRANTY_VOIDED_DATE as warrantyVoidedDate, DATE(mo.ORDER_DATE) as order_date, (SELECT SHIP_DATE FROM BASIL_ODS_PRD.XREF_SHIP xs WHERE xs.BOX_OID = xm.BOX_OID) as shipDate FROM BASIL_ODS_PRD.MASTER_ORDER mo INNER JOIN BASIL_ODS_PRD.XREF_MATERIALS xm ON xm.MO_OID = mo.MO_OID INNER JOIN BASIL_ODS_PRD.MASTER_SERIAL_NUMBER msn ON msn.MSN_OID = xm.MSN_OID INNER JOIN BASIL_ODS_PRD.MASTER_PART part ON part.PART_OID = msn.PART_OID LEFT JOIN BASIL_ODS_PRD.XREF_TECHNICIAN xt ON xt.XT_OID = xm.TECHNICIAN LEFT JOIN BASIL_ODS_PRD.EMPLOYEE_MASTER emp ON emp.EMP_OID = xt.EMP_OID LEFT JOIN BASIL_ODS_PRD.MASTER_SERIAL_NUMBER msn2 ON msn2.MSN_OID = xm.MSN_OID2 LEFT JOIN BASIL_ODS_PRD.MASTER_PART part2 ON part2.PART_OID = msn2.PART_OID LEFT JOIN BASIL_SEC_PRD.PREP_XREF_MATERIALS xrefxm ON xrefxm.MO_OID = xm.MO_OID
AND xm.XM_OID = #{id}
AND xm.STATUS IN (107, 110, 108, 111, 112)

SELECT
count(*)
FROM
BASIL_SEC_PRD.PREP_MASTER_ORDER pmo
JOIN BASIL_ODS_PRD.MASTER_CUSTOMER mc USING(MC_OID)
JOIN BASIL_SEC_PRD.SUPPORT_CLIENT_ATTRIBUTE_VALUES scavstat ON pmo.ORDER_STATUS = scavstat.SCV_OID
LEFT JOIN BASIL_SEC_PRD.XREF_RESPONSE resp USING(MO_OID)
LEFT JOIN BASIL_SEC_PRD.USERS user ON resp.RESPONSE_BY = user.U_OID
LEFT JOIN BASIL_SEC_PRD.SUPPORT_CLIENT_ATTRIBUTE_VALUES scavstatus ON pmo.ORDER_STATUS = scavstatus.SCV_OID
LEFT JOIN BASIL_SEC_PRD.SUPPORT_CLIENT_ATTRIBUTE_VALUES scavdept ON pmo.ORDER_DEPT = scavdept.SCV_OID
LEFT JOIN BASIL_SEC_PRD.SUPPORT_CLIENT_ATTRIBUTE_VALUES scavtype ON pmo.ORDER_TYPE = scavtype.SCV_OID
LEFT JOIN (
select response.* from ( select response.*,row_number() over (partition by mo_oid order by response_date desc) rn from BASIL_SEC_PRD.XREF_RESPONSE as response ) AS response where response.rn=1 ) AS res on res.MO_OID=pmo.MO_OID


        AND mc.MC_OID = #{id}


        AND

            #{item}



        AND scavdept.SCV_OID = #{department}


        AND scavtype.SCV_OID = #{type}


        AND scavstatus.SCV_OID = #{status}




        AND resp.RESPONSE_DATE = #{lastResponse}



        AND mc.CUSTOMER_ORGANIZATION = #{customerOrganization}



        AND mc.MC_OID = #{customerId}



        AND
        pmo.MO_OID IN (
        SELECT pxm.MO_OID
        FROM BASIL_SEC_PRD.PREP_XREF_MATERIALS AS pxm
        WHERE pxm.MSN_OID IN (
        SELECT msn.MSN_OID
        FROM BASIL_ODS_PRD.MASTER_SERIAL_NUMBER AS msn
        WHERE msn.SERIAL_NUMBER IN

            #{item}

        )
        )


        AND user.NAME = #{responder} OR user.NAME IS NULL


        AND pmo.ORDER_DATE BETWEEN #{createdFromDate} AND #{createdToDate}

SELECT
pmo.MO_OID as ticketId,
scavstatus.VALUE as status,
scavdept.VALUE as department,
scavtype.VALUE as type,
mc.CUSTOMER_ORGANIZATION as customerOrganization,
pmo.ORDER_DATE as createdDate,
resp.RESPONSE_DATE as lastResponse,
user.NAME as responder

FROM
BASIL_SEC_PRD.PREP_MASTER_ORDER pmo
JOIN BASIL_ODS_PRD.MASTER_CUSTOMER mc USING(MC_OID)
JOIN BASIL_SEC_PRD.SUPPORT_CLIENT_ATTRIBUTE_VALUES scavstat ON pmo.ORDER_STATUS = scavstat.SCV_OID
LEFT JOIN BASIL_SEC_PRD.XREF_RESPONSE resp USING(MO_OID)
LEFT JOIN BASIL_SEC_PRD.USERS user ON resp.RESPONSE_BY = user.U_OID

LEFT JOIN BASIL_SEC_PRD.SUPPORT_CLIENT_ATTRIBUTE_VALUES scavstatus ON pmo.ORDER_STATUS = scavstatus.SCV_OID
LEFT JOIN BASIL_SEC_PRD.SUPPORT_CLIENT_ATTRIBUTE_VALUES scavdept ON pmo.ORDER_DEPT = scavdept.SCV_OID
LEFT JOIN BASIL_SEC_PRD.SUPPORT_CLIENT_ATTRIBUTE_VALUES scavtype ON pmo.ORDER_TYPE = scavtype.SCV_OID
LEFT JOIN (
select response.* from ( select response.*,row_number() over (partition by mo_oid order by response_date desc) rn from BASIL_SEC_PRD.XREF_RESPONSE as response ) AS response where response.rn=1 ) AS res on res.MO_OID=pmo.MO_OID


        AND mc.MC_OID = #{id}


        AND

            #{item}



        AND scavdept.SCV_OID = #{department}


        AND scavtype.SCV_OID = #{type}


        AND scavstatus.SCV_OID = #{status}



        AND mc.CUSTOMER_ORGANIZATION = #{customerOrganization}



        AND resp.RESPONSE_DATE = #{lastResponse}



        AND mc.MC_OID = #{customerId}



        AND
        pmo.MO_OID IN (
        SELECT pxm.MO_OID
        FROM BASIL_SEC_PRD.PREP_XREF_MATERIALS AS pxm
        WHERE pxm.MSN_OID IN (
        SELECT msn.MSN_OID
        FROM BASIL_ODS_PRD.MASTER_SERIAL_NUMBER AS msn
        WHERE msn.SERIAL_NUMBER IN

            #{item}

        )
        )



        AND LOWER(user.NAME) LIKE CONCAT ('%', LOWER(#{responder}), '%')


        AND pmo.ORDER_DATE BETWEEN #{createdFromDate} AND #{createdToDate}



    ORDER BY ${sortColumns}

LIMIT #{offset,jdbcType=INTEGER},#{count,jdbcType=INTEGER}

SELECT hpcf.SN as serialNumber, hpcf.`Full_PN#` as model, hpcf.`Version_#` as version, msn.WARRANTY_END_DATE as warrantyExpDate, rc.PART_NUMBER_SHORT, rc.CUSTOMER AS COMPANY, rc.COSMETIC as cosmeticPrice, rc.DIAGNOSTIC as diagnosticPrice, rc.MINOR as minorPrice FROM BASIL_ODS_PRD.MASTER_SERIAL_NUMBER msn JOIN BASIL_SBX_PRD.HIST_PREP_CHINA_FILE hpcf ON hpcf.SN = msn.SERIAL_NUMBER JOIN BASIL_SBX_PRD.REPAIR_COST rc ON LEFT(hpcf.`Full_PN#`, LOCATE('-', hpcf.`Full_PN#`) - 1) = rc.PART_NUMBER_SHORT
msn.SERIAL_NUMBER = #{serialNumber}
AND (rc.CUSTOMER = #{companyId} OR rc.CUSTOMER IS NULL)
ORDER BY rc.CUSTOMER DESC
LIMIT 1;

SELECT SERIAL_NUMBER as serialNumber, msnOID, xmOID, warrantyExpDate, warrantyStatus, model, version, cosmeticPrice, diagnosticPrice, minorPrice, existInAnotherTicket FROM( SELECT msn.SERIAL_NUMBER, xm.MSN_OID as msnOID, CASE WHEN msn.WARRANTY_VOIDED_DATE IS NOT NULL THEN msn.WARRANTY_VOIDED_DATE ELSE msn.WARRANTY_END_DATE END AS warrantyExpDate, CASE WHEN msn.WARRANTY_END_DATE IS NULL AND msn.WARRANTY_VOIDED_DATE IS NULL THEN 'N/A' WHEN CURRENT_DATE < COALESCE (msn.WARRANTY_VOIDED_DATE, msn.WARRANTY_END_DATE) THEN 'Under Warranty' ELSE 'Out Of Warranty' END AS warrantyStatus, mp.PART_NUMBER_LONG AS model, mp.VERSION_NUMBER AS version, rc.COSMETIC AS cosmeticPrice, rc.DIAGNOSTIC AS diagnosticPrice, rc.MINOR AS minorPrice, xm.XM_OID as xmOID, IF(xm.XM_OID IS NULL OR xm.STATUS = 113, FALSE, TRUE) AS existInAnotherTicket, ROW_NUMBER() OVER (PARTITION BY msn.SERIAL_NUMBER ORDER BY IF(xm.XM_OID IS NULL OR xm.STATUS = 113, FALSE, TRUE) DESC) AS RN FROM BASIL_ODS_PRD.MASTER_SERIAL_NUMBER msn LEFT JOIN BASIL_ODS_PRD.MASTER_PART mp ON msn.PART_OID = mp.PART_OID LEFT JOIN BASIL_ODS_PRD.XREF_MATERIALS xm ON msn.MSN_OID = xm.MSN_OID LEFT JOIN BASIL_SBX_PRD.REPAIR_COST rc ON LEFT(mp.PART_NUMBER_LONG, LOCATE('-', mp.PART_NUMBER_LONG) - 1) = rc.PART_NUMBER_SHORT
msn.SERIAL_NUMBER IN
#{item, jdbcType=INTEGER}
AND ( rc.CUSTOMER = #{companyId} OR ( rc.CUSTOMER IS NULL AND NOT EXISTS ( SELECT 1 FROM BASIL_SBX_PRD.REPAIR_COST rc2 WHERE rc2.PART_NUMBER_SHORT = rc.PART_NUMBER_SHORT
AND rc2.CUSTOMER = #{companyId}
) ) )
) AS CTE
(existInAnotherTicket = 1) OR (existInAnotherTicket = 0 AND RN = 1);
